INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q121289734', '1999 Comorian coup d''état', 'The 1999 Comorian coup d''état was a two-day long bloodless military takeover in the Comoros led by Colonel Azali Assoumani from April 29 to April 30, resulting in the overthrow of interim president Tadjidine Ben Said Massonde. The coup was ostensibly carried out to restore order and prevent further attacks on Anjouanese residents in Grande Comore amid the country''s secession crisis involving the islands of Anjouan and Mohéli.', 1999, 4, 30, NULL, NULL, NULL, 'day', '30 April 1999', 34, 'https://en.wikipedia.org/wiki/1999_Comorian_coup_d''%C3%A9tat'),
